var base="https://m.ranwen.net";
var k=java.encodeURI(String(key),"UTF8");
var html=java.ajax(base+"/user/search.html?q="+k);
function getVar(n){
  var reg=new RegExp("var\\s+"+n+"\\s*=\\s*\"([^\"]*)\"");
  var m=html.match(reg);
  return m?m[1]:"";
}
var ns="vw,abw,ru,jrt,van,fw,cwl,gpr,uyoo,tz,euu,tsn,eju,um,fp,dvm,jpk,deblkx,ht,azy,sna,wqx,fpp,rup,jwj,bgt,qp,yf,cw,wq,sign".split(",");
var body="q="+k;
for(var i=0;i<ns.length;i++){
  var n=ns[i];
  body+="&"+n+"="+java.encodeURI(String(getVar(n)),"UTF8");
}
var opt={
  "method":"POST",
  "body":String(body),
  "charset":"utf-8",
  "headers":{
    "X-Requested-With":"XMLHttpRequest",
    "Content-Type":"application/x-www-form-urlencoded; charset=UTF-8",
    "Referer":base+"/user/search.html?q="+k
  }
};
base+"/api/search,"+JSON.stringify(opt)
